use implexity_core::{CaeError,CaeResult};
use implexity_linalg::sparse::CsrMatrix;
use implexity_solve::{matrix::{Jacobian,checked_product},factorization::Factorization,local_condensation::LocalEliminationPartition,multirate_coupling::{FluxDrivenField,FieldJacobians},time_stepper::StepParameters};
use crate::moving_contact::{contact_field::ContactField,contact_set_kinematics::ContactSetKinematics};
fn fail(s:&str)->CaeError{CaeError::contract(s)}
fn down(x:f64)->f64{if x.is_nan()||x==f64::NEG_INFINITY{x}else if x==0.{-f64::from_bits(1)}else{f64::from_bits(if x>0.{x.to_bits()-1}else{x.to_bits()+1})}}
fn up(x:f64)->f64{-down(-x)}
pub struct DirectionalKktPolicy{pub condition_limit:f64,pub complementary_residual_tolerance:f64,pub maximum_iterations:usize}
pub struct BiactiveNativeDirectionalOwner{jacobians:FieldJacobians,factor:Factorization,gap_current:CsrMatrix,gap_design:Jacobian,force_columns:Vec<Vec<f64>>,delassus:Vec<Vec<f64>>,native:usize,contacts:usize,margin:f64,frobenius_squared:f64,inverse_force_scales:Vec<f64>,policy:DirectionalKktPolicy,pub native_condition_estimate:f64}
pub struct NativeContactDirection{pub previous:Vec<f64>,pub flux:Vec<f64>,pub design:Vec<f64>,pub time_scale:f64}
pub struct BiactiveNativeDirectionalResult{pub current:Vec<f64>,pub scaled_gap_direction:Vec<f64>,pub multiplier_direction:Vec<f64>,pub complementary_residual:f64,pub iterations:usize,pub computed_delassus_strong_monotonicity_lower:f64,pub scope:&'static str,ray_binding:Vec<u64>}
impl BiactiveNativeDirectionalOwner{
 pub fn from_native<F:FluxDrivenField,L:ContactSetKinematics>(field:&ContactField<F,L>,current:&[f64],previous:&[f64],flux:&[f64],p:StepParameters<'_>,residual_tolerance:f64,policy:DirectionalKktPolicy)->CaeResult<Self>{
  let n=field.law().native_states();let m=field.law().contact_count();if m==0||current.len()!=n+m||previous.len()!=n+m||current.iter().chain(previous).chain(flux).chain(p.design).any(|v|!v.is_finite())||!p.time_scale.is_finite()||p.time_scale<=0.||!residual_tolerance.is_finite()||residual_tolerance<=0.||!policy.condition_limit.is_finite()||policy.condition_limit<=1.||!policy.complementary_residual_tolerance.is_finite()||policy.complementary_residual_tolerance<=0.||policy.maximum_iterations==0{return Err(fail("native directional KKT explicit domain/policy"));}
  let(gaps,g)=field.law().scaled_gap_rows(current,p.design)?;if gaps.len()!=m||gaps.iter().any(|g|*g!=0.)||current[n..].iter().any(|l|*l!=0.){return Err(fail("all-biactive directional KKT requires exact zero native gap and multiplier"));}field.check_state_domain(1,current,previous,p)?;
  let residual=field.residual(1,current,previous,flux,p)?;if residual.len()!=n+m{return Err(fail("native directional residual shape"));}if residual.iter().any(|v|!v.is_finite()||v.abs()>residual_tolerance){return Err(fail("native directional KKT requires an actual residual-admitted base"));}
  let j=field.jacobians(1,current,previous,flux,p)?;let full=j.current.to_csr()?;if full.nrows()!=n+m||full.ncols()!=n+m||j.time_scale.len()!=n+m||j.time_scale.iter().any(|v|!v.is_finite()){return Err(fail("native directional current/time Jacobian shape or finite domain"));}let mut ri=vec![];let mut ci=vec![];let mut vs=vec![];let mut b=vec![vec![0.;n];m];for i in 0..n{let(js,v)=full.row(i);for(&k,&x)in js.iter().zip(v){if k<n{ri.push(i);ci.push(k);vs.push(x);}else{b[k-n][i]+=x;}}}let k=CsrMatrix::from_triplets(n,n,&ri,&ci,&vs).map_err(|e|fail(&e.to_string()))?;
  let partition=field.local_elimination_groups()?.map(|groups|LocalEliminationPartition::new(n,groups).map_err(|e|fail(&e.to_string()))).transpose()?;let factor=Factorization::new_with_partition(Jacobian::Csr(k),n,policy.condition_limit,None,partition.as_ref())?;let condition=factor.condition();let gap_current=g.to_csr()?;if gap_current.nrows()!=m||gap_current.ncols()!=n+m{return Err(fail("native directional gap row shape"));}for r in 0..m{let(js,v)=gap_current.row(r);if js.iter().zip(v).any(|(c,x)|*c>=n&&*x!=0.){return Err(fail("native directional gap depends on multiplier"));}}
  let inverse_force_scales=field.law().inverse_force_scales(current,p)?;if inverse_force_scales.len()!=m||inverse_force_scales.iter().any(|v|!v.is_finite()||*v<=0.){return Err(fail("native directional force normalization"));}let mut w=vec![vec![0.;m];m];for q in 0..m{let x=factor.solve(&b[q].iter().map(|x|x/inverse_force_scales[q]).collect::<Vec<_>>(),false)?.0;for r in 0..m{let(js,v)=gap_current.row(r);w[r][q]=-js.iter().zip(v).filter(|(c,_)|**c<n).map(|(c,a)|a*x[*c]).sum::<f64>();}}
  let mut margin=f64::INFINITY;let mut norm=0.;for i in 0..m{let mut lower=down(w[i][i]);for q in 0..m{if !w[i][q].is_finite(){return Err(fail("native directional Delassus overflow"));}norm=up(norm+up(w[i][q]*w[i][q]));if q!=i{let s=up(0.5*up(w[i][q]+w[q][i]));let lo=down(0.5*down(w[i][q]+w[q][i]));lower=down(lower-up(s.abs().max(lo.abs())));}}margin=margin.min(lower);}
  if !margin.is_finite()||margin<=0.||!norm.is_finite()||norm<=0.{return Err(fail("computed native Delassus strong monotonicity not certified; directional uniqueness unresolved"));}let gd=field.law().scaled_gap_design_rows(current,p.design)?;let force_columns:Vec<_>=b.iter().zip(&inverse_force_scales).map(|(column,scale)|column.iter().map(|v|v/scale).collect::<Vec<_>>()).collect();Ok(Self{jacobians:j,factor,gap_current,gap_design:gd,force_columns,delassus:w,native:n,contacts:m,margin,frobenius_squared:norm,inverse_force_scales,policy,native_condition_estimate:condition})
 }
 pub fn solve(&self,d:&NativeContactDirection)->CaeResult<BiactiveNativeDirectionalResult>{
  if !d.time_scale.is_finite()||d.previous.iter().chain(&d.flux).chain(&d.design).any(|v|!v.is_finite()){return Err(fail("native directional input finite"));}let mut r=checked_product(&self.jacobians.previous,&d.previous,"native directional previous",false)?;let f=checked_product(&self.jacobians.flux,&d.flux,"native directional flux",false)?;let p=checked_product(&self.jacobians.design,&d.design,"native directional design",false)?;if r.len()!=self.native+self.contacts||f.len()!=r.len()||p.len()!=r.len(){return Err(fail("native directional input shape"));}for i in 0..self.native{r[i]+=f[i]+p[i]+self.jacobians.time_scale[i]*d.time_scale;}let free=self.factor.solve(&r[..self.native].iter().map(|v|-v).collect::<Vec<_>>(),false)?.0;let direct=checked_product(&self.gap_design,&d.design,"native directional gap design",false)?;if direct.len()!=self.contacts{return Err(fail("native directional direct gap shape"));}let mut b=direct;for i in 0..self.contacts{let(js,v)=self.gap_current.row(i);b[i]+=js.iter().zip(v).filter(|(j,_)|**j<self.native).map(|(j,a)|a*free[*j]).sum::<f64>();}let alpha=down(self.margin/self.frobenius_squared);if !alpha.is_finite()||alpha<=0.{return Err(fail("native directional contraction step underflow"));}let mut lambda=vec![0.;self.contacts];for iteration in 0..=self.policy.maximum_iterations{let gaps:Vec<f64>=(0..self.contacts).map(|i|b[i]+self.delassus[i].iter().zip(&lambda).map(|(a,l)|a*l).sum::<f64>()).collect();let residual=gaps.iter().zip(&lambda).map(|(g,l)|g.hypot(*l)-g-l).map(f64::abs).fold(0.,f64::max);if !residual.is_finite(){return Err(fail("native directional complementary overflow"));}if residual<=self.policy.complementary_residual_tolerance&&gaps.iter().all(|g|*g>=-self.policy.complementary_residual_tolerance){let rhs:Vec<_>=(0..self.native).map(|i|-r[i]-self.force_columns.iter().zip(&lambda).map(|(column,l)|column[i]*l).sum::<f64>()).collect();let mut state=self.factor.solve(&rhs,false)?.0;let actual_gap:Vec<f64>=(0..self.contacts).map(|i|{let(js,v)=self.gap_current.row(i);js.iter().zip(v).filter(|(j,_)|**j<self.native).map(|(j,a)|a*(state[*j]-free[*j])).sum::<f64>()+b[i]}).collect();let actual_residual=actual_gap.iter().zip(&lambda).map(|(g,l)|g.hypot(*l)-g-l).map(f64::abs).fold(0.,f64::max);if !actual_residual.is_finite()||actual_residual>self.policy.complementary_residual_tolerance||actual_gap.iter().any(|g|*g < -self.policy.complementary_residual_tolerance){return Err(fail("certified native body action does not meet directional contact residual"));}let physical_lambda:Vec<_>=lambda.iter().zip(&self.inverse_force_scales).map(|(l,s)|l/s).collect();if state.iter().chain(&actual_gap).chain(&physical_lambda).any(|v|!v.is_finite()){return Err(fail("native directional output overflow"));}state.extend(&physical_lambda);let ray_binding=actual_gap.iter().chain(&physical_lambda).chain(self.delassus.iter().flatten()).chain(&self.inverse_force_scales).map(|x|x.to_bits()).collect();return Ok(BiactiveNativeDirectionalResult{current:state,scaled_gap_direction:actual_gap,multiplier_direction:physical_lambda,complementary_residual:actual_residual,iterations:iteration,computed_delassus_strong_monotonicity_lower:self.margin,ray_binding,scope:"Hadamard directional solution of computed native selected-row all-biactive KKT with certified computed Delassus uniqueness; not an ordinary or complete-surface/window gradient"});}if iteration==self.policy.maximum_iterations{break;}for i in 0..self.contacts{lambda[i]=(lambda[i]-alpha*gaps[i]).max(0.);}}
  Err(fail("native directional complementary solve did not satisfy explicit residual budget"))
 }
}

pub struct NativeContactCotangent { pub current: Vec<f64> }
impl BiactiveNativeDirectionalOwner {
 fn strict_ray_factor(&self, base:&BiactiveNativeDirectionalResult)->CaeResult<(Factorization,Vec<bool>)>{
  if base.current.len()!=self.native+self.contacts||base.scaled_gap_direction.len()!=self.contacts||base.multiplier_direction.len()!=self.contacts||base.current.iter().chain(&base.scaled_gap_direction).chain(&base.multiplier_direction).any(|x|!x.is_finite()){return Err(fail("strict ray base shape or finite domain"));}
  let binding:Vec<u64>=base.scaled_gap_direction.iter().chain(&base.multiplier_direction).chain(self.delassus.iter().flatten()).chain(&self.inverse_force_scales).map(|x|x.to_bits()).collect();if binding!=base.ray_binding{return Err(fail("strict ray result/owner binding mismatch"));}
  let mut active=vec![];let mut rows=vec![];let mut cols=vec![];let mut values=vec![];
  for i in 0..self.contacts{let a=base.multiplier_direction[i]*self.inverse_force_scales[i];let g=base.scaled_gap_direction[i];let tol=self.policy.complementary_residual_tolerance;
   let selected=if a>tol&&g.abs()<=tol{true}else if g>tol&&a.abs()<=tol{false}else{return Err(fail("strict ray requires complementary directional margins; ties refuse"));};active.push(selected);
   for j in 0..self.contacts{let v=if selected{self.delassus[i][j]}else if i==j{1.}else{0.};if v!=0.{rows.push(i);cols.push(j);values.push(v);}}
  }
  let a=CsrMatrix::from_triplets(self.contacts,self.contacts,&rows,&cols,&values).map_err(|e|fail(&e.to_string()))?;
  Ok((Factorization::new(Jacobian::Csr(a),self.contacts,self.policy.condition_limit,None)?,active))
 }
 pub fn strict_ray_direction(&self,base:&BiactiveNativeDirectionalResult,d:&NativeContactDirection)->CaeResult<Vec<f64>>{
  let(factor,active)=self.strict_ray_factor(base)?;
  if !d.time_scale.is_finite()||d.previous.iter().chain(&d.flux).chain(&d.design).any(|x|!x.is_finite()){return Err(fail("strict ray direction finite domain"));}
  let mut r=checked_product(&self.jacobians.previous,&d.previous,"strict ray previous",false)?;let f=checked_product(&self.jacobians.flux,&d.flux,"strict ray flux",false)?;let q=checked_product(&self.jacobians.design,&d.design,"strict ray design",false)?;
  if r.len()!=self.native+self.contacts||f.len()!=r.len()||q.len()!=r.len(){return Err(fail("strict ray map shape"));}for i in 0..self.native{r[i]+=f[i]+q[i]+self.jacobians.time_scale[i]*d.time_scale;}
  let free=self.factor.solve(&r[..self.native].iter().map(|x|-x).collect::<Vec<_>>(),false)?.0;let mut rhs=checked_product(&self.gap_design,&d.design,"strict ray direct gap",false)?;
  if rhs.len()!=self.contacts{return Err(fail("strict ray gap shape"));}for i in 0..self.contacts{let(js,v)=self.gap_current.row(i);rhs[i]=if active[i]{-rhs[i]-js.iter().zip(v).filter(|(j,_)|**j<self.native).map(|(j,v)|v*free[*j]).sum::<f64>()}else{0.};}
  let a=factor.solve(&rhs,false)?.0;let rhs:Vec<_>=(0..self.native).map(|i|-r[i]-self.force_columns.iter().zip(&a).map(|(b,a)|b[i]*a).sum::<f64>()).collect();let mut out=self.factor.solve(&rhs,false)?.0;out.extend(a.iter().zip(&self.inverse_force_scales).map(|(a,s)|a/s));if out.iter().any(|x|!x.is_finite()){return Err(fail("strict ray output overflow"));}Ok(out)
 }
 pub fn strict_ray_adjoint(&self,base:&BiactiveNativeDirectionalResult,c:&NativeContactCotangent)->CaeResult<NativeContactDirection>{
  let(factor,active)=self.strict_ray_factor(base)?;if c.current.len()!=self.native+self.contacts||c.current.iter().any(|x|!x.is_finite()){return Err(fail("strict ray cotangent domain"));}
  let z=self.factor.solve(&c.current[..self.native],true)?.0;let abar:Vec<_>=(0..self.contacts).map(|i|c.current[self.native+i]/self.inverse_force_scales[i]-self.force_columns[i].iter().zip(&z).map(|(b,z)|b*z).sum::<f64>()).collect();let y=factor.solve(&abar,true)?.0;let bbar:Vec<_>=y.iter().zip(&active).map(|(y,a)|if *a{-y}else{0.}).collect();let mut freebar=vec![0.;self.native];for i in 0..self.contacts{let(js,v)=self.gap_current.row(i);for(&j,&v)in js.iter().zip(v){if j<self.native{freebar[j]+=v*bbar[i];}}}
  let extra=self.factor.solve(&freebar,true)?.0;let mut rbar=vec![0.;self.native+self.contacts];for i in 0..self.native{rbar[i]=-z[i]-extra[i];}
  let previous=checked_product(&self.jacobians.previous,&rbar,"strict ray previous adjoint",true)?;let flux=checked_product(&self.jacobians.flux,&rbar,"strict ray flux adjoint",true)?;let mut design=checked_product(&self.jacobians.design,&rbar,"strict ray design adjoint",true)?;let direct=checked_product(&self.gap_design,&bbar,"strict ray direct gap adjoint",true)?;if direct.len()!=design.len(){return Err(fail("strict ray design adjoint shape"));}for(i,v)in direct.into_iter().enumerate(){design[i]+=v;}let time_scale=self.jacobians.time_scale.iter().zip(&rbar).map(|(a,b)|a*b).sum();Ok(NativeContactDirection{previous,flux,design,time_scale})
 }
}
